// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetJwks The signing keys
	// (GET /.well-known/jwks.json)
	GetJwks(w http.ResponseWriter, r *http.Request, params GetJwksParams)
	// GetServerMetadata Server metadata (RFC 8414)
	// (GET /.well-known/oauth-authorization-server)
	GetServerMetadata(w http.ResponseWriter, r *http.Request)
	// DeleteAccount Close an account
	// (DELETE /v1/accounts/{accountId})
	DeleteAccount(w http.ResponseWriter, r *http.Request, accountId AccountId, params DeleteAccountParams)
	// StartSupportIdentifierChange Start an identifier change for an account whose old address is lost
	// (POST /v1/accounts/{accountId}/identifier-changes)
	StartSupportIdentifierChange(w http.ResponseWriter, r *http.Request, accountId AccountId, params StartSupportIdentifierChangeParams)
	// ResetAccountMfa Reset a lost second factor
	// (POST /v1/accounts/{accountId}/mfa/reset)
	ResetAccountMfa(w http.ResponseWriter, r *http.Request, accountId AccountId, params ResetAccountMfaParams)
	// SetAccountRoles Replace an account's roles
	// (PUT /v1/accounts/{accountId}/roles)
	SetAccountRoles(w http.ResponseWriter, r *http.Request, accountId AccountId, params SetAccountRolesParams)
	// RevokeAccountSessions Revoke every session of an account
	// (POST /v1/accounts/{accountId}/sessions/revoke)
	RevokeAccountSessions(w http.ResponseWriter, r *http.Request, accountId AccountId, params RevokeAccountSessionsParams)
	// SetAccountStatus Set an account's status
	// (PUT /v1/accounts/{accountId}/status)
	SetAccountStatus(w http.ResponseWriter, r *http.Request, accountId AccountId, params SetAccountStatusParams)
	// BatchGetAccounts Get accounts by id
	// (POST /v1/directory/accounts/batch-get)
	BatchGetAccounts(w http.ResponseWriter, r *http.Request, params BatchGetAccountsParams)
	// ListAccounts List accounts by status, role and creation time
	// (POST /v1/directory/accounts/list)
	ListAccounts(w http.ResponseWriter, r *http.Request, params ListAccountsParams)
	// SearchAccounts Find an account by a verified identifier
	// (POST /v1/directory/accounts/search)
	SearchAccounts(w http.ResponseWriter, r *http.Request, params SearchAccountsParams)
	// ResolveDeliveryReferences Resolve the references of a delivery request at send time
	// (POST /v1/hooks/delivery/resolve)
	ResolveDeliveryReferences(w http.ResponseWriter, r *http.Request)
	// IntrospectToken Introspect an access token (RFC 7662)
	// (POST /v1/introspect)
	IntrospectToken(w http.ResponseWriter, r *http.Request)
	// CreateInvitation Invite an email to a new account with roles
	// (POST /v1/invitations)
	CreateInvitation(w http.ResponseWriter, r *http.Request, params CreateInvitationParams)
	// AcceptInvitation Accept an invitation, set the password and supply the other required identifiers
	// (POST /v1/invitations/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in account
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change the display name or the locale
	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// StartEmailChange Start an email change
	// (POST /v1/me/email-changes)
	StartEmailChange(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password
	// (POST /v1/me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// StartPhoneChange Start a phone change
	// (POST /v1/me/phone-changes)
	StartPhoneChange(w http.ResponseWriter, r *http.Request)
	// ResendPhoneChange Send the code to the new number again
	// (POST /v1/me/phone-changes/{flowId}/resend)
	ResendPhoneChange(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// VerifyPhoneChange Verify the new number and apply the change
	// (POST /v1/me/phone-changes/{flowId}/verify)
	VerifyPhoneChange(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// RegenerateRecoveryCodes Replace every recovery code
	// (POST /v1/me/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// SignOutOtherSessions Sign out of every other session
	// (DELETE /v1/me/sessions)
	SignOutOtherSessions(w http.ResponseWriter, r *http.Request)
	// ListMySessions The account's live sessions
	// (GET /v1/me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// RevokeMySession Sign out of one session
	// (DELETE /v1/me/sessions/{sessionId})
	RevokeMySession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// RemoveTotp Turn TOTP off
	// (DELETE /v1/me/totp)
	RemoveTotp(w http.ResponseWriter, r *http.Request)
	// StartTotpEnrolment Enable TOTP (self-service), step one
	// (POST /v1/me/totp)
	StartTotpEnrolment(w http.ResponseWriter, r *http.Request)
	// ConfirmTotpEnrolment Enable TOTP (self-service), step two
	// (POST /v1/me/totp/confirm)
	ConfirmTotpEnrolment(w http.ResponseWriter, r *http.Request)
	// StartTotpReplacement Start replacing the TOTP factor (for example, a new phone)
	// (POST /v1/me/totp/replacement)
	StartTotpReplacement(w http.ResponseWriter, r *http.Request)
	// ConfirmTotpReplacement Confirm the new TOTP factor with a first code
	// (POST /v1/me/totp/replacement/{flowId}/confirm)
	ConfirmTotpReplacement(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// IssueServiceToken Client-credentials token (RFC 6749 §4.4, RFC 7523)
	// (POST /v1/oauth/token)
	IssueServiceToken(w http.ResponseWriter, r *http.Request)
	// RequestPasswordReset Request a reset link
	// (POST /v1/password-resets)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// StartPasswordReset Open a reset link
	// (POST /v1/password-resets/start)
	StartPasswordReset(w http.ResponseWriter, r *http.Request)
	// CompletePasswordReset Set the new password
	// (POST /v1/password-resets/{flowId}/complete)
	CompletePasswordReset(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// StartRegistration Start a registration
	// (POST /v1/registrations)
	StartRegistration(w http.ResponseWriter, r *http.Request)
	// RequestRegistrationResume Resume a registration or invitation whose handle was lost
	// (POST /v1/registrations/resume)
	RequestRegistrationResume(w http.ResponseWriter, r *http.Request)
	// VerifyRegistrationResume Resume a flow with a code
	// (POST /v1/registrations/resume/verify)
	VerifyRegistrationResume(w http.ResponseWriter, r *http.Request)
	// CompleteRegistration Activate the account and sign in
	// (POST /v1/registrations/{flowId}/complete)
	CompleteRegistration(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// ResendRegistrationVerification Send the verification for one identifier again
	// (POST /v1/registrations/{flowId}/resend)
	ResendRegistrationVerification(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// VerifyRegistrationCode Verify an identifier with a code
	// (POST /v1/registrations/{flowId}/verify)
	VerifyRegistrationCode(w http.ResponseWriter, r *http.Request, flowId FlowId)
	// SignIn Sign in with an identifier and a password
	// (POST /v1/sessions)
	SignIn(w http.ResponseWriter, r *http.Request)
	// SignOut Sign out of the current session
	// (DELETE /v1/sessions/current)
	SignOut(w http.ResponseWriter, r *http.Request)
	// CompleteSignIn Second step of a sign-in, with a TOTP code or a recovery code
	// (POST /v1/sessions/mfa)
	CompleteSignIn(w http.ResponseWriter, r *http.Request)
	// StartEnrolment Start forced TOTP enrolment (a client that requires MFA)
	// (POST /v1/sessions/mfa/enrolment)
	StartEnrolment(w http.ResponseWriter, r *http.Request)
	// ConfirmEnrolment Confirm TOTP enrolment with a first code and receive the session
	// (POST /v1/sessions/mfa/enrolment/confirm)
	ConfirmEnrolment(w http.ResponseWriter, r *http.Request)
	// RequestSignInOtp Sign in, first factor, by a code sent to a sign-in identifier
	// (POST /v1/sessions/otp)
	RequestSignInOtp(w http.ResponseWriter, r *http.Request)
	// VerifySignInOtp Verify the sign-in code
	// (POST /v1/sessions/otp/verify)
	VerifySignInOtp(w http.ResponseWriter, r *http.Request)
	// RefreshSession Rotate the refresh token and issue a new access token
	// (POST /v1/sessions/refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// ConfirmVerificationLink Confirm an emailed link
	// (POST /v1/verification-links/confirm)
	ConfirmVerificationLink(w http.ResponseWriter, r *http.Request)
}

